pub fn is_non_prime(n: u64) -> bool {
    // By definition, 2 and 3 are prime.
    if n <= 3 {
        return false;
    }
    // Even numbers greater than 2 are composite.
    if n % 2 == 0 {
        return true;
    }
    // Check odd divisors from 3 up to √n.
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return true;
        }
        i += 2;
    }
    false
}

